      const up = t.v.toUpperCase()
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            bad()
          }
        }
        return { n: 'call', name: up, args }
      }
      if (up === 'TRUE') return { n: 'bool', v: true }
      if (up === 'FALSE') return { n: 'bool', v: false }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.k !== 'word') bad()
        p++
        const up2 = t2.v.toUpperCase()
        if (isOp('(') || up2 === 'TRUE' || up2 === 'FALSE') bad()
        const a = parseAddr(up), b = parseAddr(up2)
        if (a && b) {
          for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
            for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) deps.add(c * 1000 + r)
        }
        return { n: 'range', a, b }
      }
      const a = parseAddr(up)
      addDep(a)
      return { n: 'ref', a }
    }
    bad()
  }
  try {
    const ast = cmp()
    if (p !== toks.length) return null
    return { ast, deps }
  } catch (e) {
    if (e === BAD) return null
    throw e
  }
}

// ---- evaluation
const parsed = new Map()
for (const [key, c] of cells) {
  const ct = c.content
  if (ct[0] === '=') {
    const f = parseFormula(ct.slice(1))
    c.formula = f
  }
}

const memo = new Map()
const active = new Set()

function cellValue(key) {
  if (memo.has(key)) return memo.get(key)
  const c = cells.get(key)
  if (!c) return ZERO
  if (active.has(key)) return err('#CYCLE!')
  active.add(key)
  let v
  const ct = c.content
  if (ct[0] === '=') v = c.formula ? ev(c.formula.ast) : err('#ERR!')
  else if (ct === '') v = ZERO
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(ct)) v = num(Number(ct))
  else if (ERRS.has(ct)) v = err(ct)
  else v = { t: 's', v: ct }
  active.delete(key)
  memo.set(key, v)
  return v
}

function fin(x) { return Number.isFinite(x) ? num(x) : err('#DIV/0!') }
function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}
function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const RANK = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return RANK[a.t] - RANK[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') return cpCompare(a.v, b.v)
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

function expandRange(node) {
  const { a, b } = node
  if (!a || !b) return [err('#REF!')]
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(cellValue(c * 1000 + r))
  return out
}

function ev(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return { t: 'b', v: n.v }
    case 'ref': return n.a ? cellValue(n.a.key) : err('#REF!')
    case 'range': return err('#ERR!')
    case 'un': {
      const x = ev(n.x)
      if (x.t === 'e') return x
      const y = toNum(x)
      if (y.t === 'e') return y
      return n.op === '-' ? num(-y.v) : y
    }
    case 'bin': {
      const l = ev(n.l)
      if (l.t === 'e') return l
      const r = ev(n.r)
      if (r.t === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const d = compare(l, r)
        const res = n.op === '=' ? d === 0 : n.op === '<>' ? d !== 0 : n.op === '<' ? d < 0
          : n.op === '<=' ? d <= 0 : n.op === '>' ? d > 0 : d >= 0
        return { t: 'b', v: res }
      }
      const a = toNum(l)
      if (a.t === 'e') return a
      const b = toNum(r)
      if (b.t === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        case '^': return fin(Math.pow(a.v, b.v))
      }
    }
    case 'call': return call(n)
  }
}

function call(n) {
  const { name, args } = n
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const c = ev(args[0])
    if (c.t === 'e') return c
    let truth
    if (c.t === 'b') truth = c.v
    else if (c.t === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return ev(truth ? args[1] : args[2])
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const x = ev(args[0])
    if (x.t === 'e') return x
    const y = toNum(x)
    if (y.t === 'e') return y
    return fin(Math.abs(y.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.n === 'range') vals.push(...expandRange(a))
    else vals.push(ev(a))
  }
  for (const v of vals) if (v.t === 'e') return v
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return fin(Math.min(...nums))
    case 'MAX': return fin(Math.max(...nums))
    case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
}

function show(v) {
  if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

// ---- output
const keys = [...cells.keys()].sort((a, b) => a - b)
let out = ''
for (const k of keys) {
  const c = cells.get(k)
  if (mode === 'values') out += `${c.a.name}=${show(cellValue(k))}\n`
  else {
    let s = `${c.a.name}:`
    if (c.formula) {
      for (const d of [...c.formula.deps].sort((a, b) => a - b)) s += ' ' + keyName(Math.floor(d / 1000), d % 1000)
    }
    out += s + '\n'
  }
}
process.stdout.write(out)
